49	// ──────────────────────────────────────────────────────────────────
50	// buildRoutinePayload
51	// ──────────────────────────────────────────────────────────────────
52	
53	export interface RoutinePayload {
54	  title: string;
55	  exercises: HevyRoutineExercise[];
56	  /** Exercise template IDs from the routine that had no mapping */
57	  unmapped: string[];
58	}
59	
60	/**
61	 * Build a Hevy routine payload from a program routine + exercise template mappings.
62	 * Exercises without a mapping are collected in `unmapped` and omitted from
63	 * the payload.
64	 */
65	export function buildRoutinePayload(
66	  routine: Routine,
67	  mappings: ExerciseTemplateMappingRow[]
68	): RoutinePayload {
69	  const mappingMap = new Map(
70	    mappings.map((m) => [m.program_template_id, m.hevy_template_id])
71	  );
72	
73	  const exercises: HevyRoutineExercise[] = [];
74	  const unmapped: string[] = [];
75	
76	  for (const exercise of routine.exercises) {
77	    const hevyId = mappingMap.get(exercise.exerciseTemplateId);
78	    if (!hevyId) {
79	      unmapped.push(exercise.exerciseTemplateId);
80	      continue;
81	    }
82	
83	    const sets = parseSetsString(exercise.sets);
84	
85	    exercises.push({
86	      exercise_template_id: hevyId,
87	      sets,
88	      notes: exercise.notes,
89	    });
90	  }
91	
92	  return { title: routine.title, exercises, unmapped };
93	}
94	
95	// ──────────────────────────────────────────────────────────────────
96	// Folder assignments & reconciliation
97	// ──────────────────────────────────────────────────────────────────
98	
99	export interface RoutineFolderAssignment {
100	  routineId: string;
101	  routineTitle: string;
102	  folderName: string;
103	}
104	
105	/**
106	 * Compute which Hevy folder each routine should belong to.
107	 * Uses routine.folderGroup if set, falls back to "Daily" for isDaily,
108	 * or programTitle for everything else.
109	 */
110	export function computeFolderAssignments(
111	  routines: Routine[],
112	  programTitle: string
113	): RoutineFolderAssignment[] {
114	  return routines.map((r) => ({
115	    routineId: r.id,
116	    routineTitle: r.title,
117	    folderName: r.folderGroup ?? (r.isDaily ? "Daily" : programTitle),
118	  }));
119	}
120	
121	export interface RoutineReconciliation {
122	  programRoutineId: string;
123	  action: "create" | "update";
124	  existingHevyRoutineId?: string;
125	  folderName: string;
126	}
127	
128	/**
129	 * Reconcile program routines against existing Hevy routines.
130	 * Checks D1 mappings first, then matches by title within the target folder.
131	 */
132	export function reconcileRoutines(
133	  assignments: RoutineFolderAssignment[],
134	  existingHevyRoutines: Array<{ id: string; title: string; folder_id?: number }>,
135	  folderNameToId: Map<string, number>,
136	  existingMappings: Map<string, string>
137	): RoutineReconciliation[] {
138	  return assignments.map((a) => {
139	    // First check existing D1 mapping
140	    const mappedId = existingMappings.get(a.routineId);
141	    if (mappedId) {
142	      return { programRoutineId: a.routineId, action: "update" as const, existingHevyRoutineId: mappedId, folderName: a.folderName };
143	    }
144	    // Then check Hevy by title + folder
145	    const targetFolderId = folderNameToId.get(a.folderName);
146	    if (targetFolderId !== undefined) {
147	      const match = existingHevyRoutines.find(
148	        (r) => r.title === a.routineTitle && r.folder_id === targetFolderId
149	      );
150	      if (match) {
151	        return { programRoutineId: a.routineId, action: "update" as const, existingHevyRoutineId: match.id, folderName: a.folderName };
152	      }
153	    }
154	    return { programRoutineId: a.routineId, action: "create" as const, folderName: a.folderName };
155	  });
156	}
157	
158	// ──────────────────────────────────────────────────────────────────
159	// buildExerciseTemplatePayload
160	// ──────────────────────────────────────────────────────────────────
161	
162	export interface ExerciseTemplatePayload {
163	  title: string;
164	  exercise_type: string;
165	  equipment_category: string;
166	  primary_muscle_group: string;
167	  other_muscles: string[];
168	}
169	
170	/**
171	 * Build a Hevy exercise template creation payload from a domain ExerciseTemplate.
172	 * Pure mapping from domain shape (camelCase) to wire shape (snake_case).
173	 */
174	export function buildExerciseTemplatePayload(
175	  template: ExerciseTemplate
176	): ExerciseTemplatePayload {
177	  return {
178	    title: template.title,
179	    exercise_type: template.type,
180	    equipment_category: template.equipmentCategory,
181	    primary_muscle_group: template.primaryMuscleGroup,
182	    other_muscles: template.secondaryMuscleGroups ?? [],
183	  };
184	}
185	
186	// ──────────────────────────────────────────────────────────────────
187	// matchCompletions
188	// ──────────────────────────────────────────────────────────────────
189	
190	export interface CompletionMatch {
191	  queueItemId: number;
192	  workoutId: string;
193	}
194	
195	/**
196	 * Match Hevy workouts to queue items by comparing each workout's routine ID
197	 * (obtained via `getRoutineId`) to the `hevy_routine_id` stored on the queue
198	 * item.
199	 *
200	 * Each workout is matched to at most one queue item.
201	 */
202	export function matchCompletions(
203	  items: Pick<QueueItemRow, "id" | "hevy_routine_id">[],
204	  workouts: HevyWorkout[],
205	  getRoutineId: (workout: HevyWorkout) => string | null
206	): CompletionMatch[] {
207	  // Build a map: routine_id → queue item id (first match wins)
208	  const routineToItem = new Map<string, number>();
209	  for (const item of items) {
210	    if (item.hevy_routine_id && !routineToItem.has(item.hevy_routine_id)) {
211	      routineToItem.set(item.hevy_routine_id, item.id);
212	    }
213	  }
214	
215	  const matches: CompletionMatch[] = [];
216	  const usedItems = new Set<number>();
217	
218	  for (const workout of workouts) {
219	    const routineId = getRoutineId(workout);
220	    if (!routineId) continue;
221	
222	    const itemId = routineToItem.get(routineId);
223	    if (itemId !== undefined && !usedItems.has(itemId)) {
224	      matches.push({ queueItemId: itemId, workoutId: workout.id });
225	      usedItems.add(itemId);
226	    }
227	  }
228	
229	  return matches;
230	}
231	
232	// ──────────────────────────────────────────────────────────────────
233	// autoMatchExercises
234	// ──────────────────────────────────────────────────────────────────
235	
236	/**
237	 * Normalize an exercise name for fuzzy matching:
238	 * - Lowercase
239	 * - Strip non-alphanumeric characters (spaces, hyphens, punctuation)
240	 * - Strip a trailing 's' (basic singular/plural normalisation)
241	 */
242	function normalizeName(name: string): string {
243	  return name
244	    .toLowerCase()
245	    .replace(/[^a-z0-9]/g, "")
246	    .replace(/s$/, "");
247	}
248	
249	/**
250	 * Attempt to automatically match our exercise templates to Hevy exercise
251	 * template IDs using normalized title comparison. Supports partial matching
252	 * (one normalized name contains the other).
253	 *
254	 * Returns a Map of our template ID → Hevy template ID for every template
255	 * that could be matched.
256	 */
257	export function autoMatchExercises(
258	  ourTemplates: ExerciseTemplate[],
259	  hevyTemplates: HevyExerciseTemplate[]
260	): Map<string, string> {
261	  const result = new Map<string, string>();
262	
263	  // Pre-normalize Hevy template titles
264	  const normalizedHevy = hevyTemplates.map((t) => ({
265	    id: t.id,
266	    norm: normalizeName(t.title),
267	  }));
268	
269	  for (const template of ourTemplates) {
270	    const normOurs = normalizeName(template.title);
271	
272	    // Prefer exact match first
273	    let matched = normalizedHevy.find((t) => t.norm === normOurs);
274	
275	    // Fall back to partial match (one contains the other)
276	    if (!matched) {
277	      matched = normalizedHevy.find(
278	        (t) => t.norm.includes(normOurs) || normOurs.includes(t.norm)
279	      );
280	    }
281	
282	    if (matched) {
283	      result.set(template.id, matched.id);
284	    }
285	  }
286	
287	  return result;
288	}
