import type { Program } from "../types";
import {
  clearPendingStateForUser,
  insertProgram,
  getExerciseTemplateMappings,
  getRoutineMappings,
  insertQueueItems,
  bulkSetQueueItemRoutineIds,
} from "../storage/queries";
import { generatePlaylist } from "../domain/queue";
import { buildRoutinePayload, autoMatchExercises, computeFolderAssignments, reconcileRoutines } from "../domain/hevy-sync";
import { mapToHevyEnums } from "../domain/hevy-enums";
import { HevyClient } from "../hevy/client";

/**
 * Activate a program: clear old pending queue and mappings, store in D1,
 * sync to Hevy (exercise templates + routines), then generate queue.
 * Reused by both initial setup (handleSetup) and program import (handleImportProgram).
 */
export async function activateProgram(
  db: D1Database,
  userId: string,
  program: Program,
  programJsonStr: string,
  templateId: string,
  apiKey: string | undefined
): Promise<void> {
  const template = program.weekTemplates.find((t) => t.id === templateId);
  if (!template) throw new Error(`Week template "${templateId}" not found in program`);

  // 1. Clear existing pending queue items and mappings atomically (preserve completed history)
  // Clear globally (no programId) since we're replacing the active program
  await clearPendingStateForUser(db, userId);

  // 2. Insert program (deactivates previous via batch in insertProgram) — get the new row ID
  const programId = await insertProgram(db, userId, programJsonStr);

  // 3. Generate queue playlist and insert items — done BEFORE Hevy sync so a Hevy API
  // failure or timeout can't leave the program active with an empty queue.
  const weeks = program.meta.durationWeeks || 8;
  const playlist = generatePlaylist(template, program.routines, weeks);
  if (playlist.length > 0) {
    await insertQueueItems(db, userId, playlist, programId);
  }

  // 4. Hevy exercise template & routine creation (only with API key)
  // Wrapped in try-catch: Hevy sync is optional — a failure is logged but does not
  // abort activation. Queue items are already in D1; hevy_routine_id will be null
  // until the user pushes routines individually or re-imports.
  const routineIdMap = new Map<string, string>();
  if (apiKey) {
    try {
      const client = new HevyClient(apiKey);

      // b. Fetch all Hevy exercise templates
      const hevyTemplates = await client.getAllExerciseTemplates();

      // c. Auto-match our templates to Hevy's by normalized title
      const matched = autoMatchExercises(program.exerciseTemplates, hevyTemplates);

      // d. Create custom Hevy exercise templates for unmatched
      const customCreated = new Set<string>();
      for (const et of program.exerciseTemplates) {
        if (!matched.has(et.id)) {
          const enums = mapToHevyEnums(et);
          const created = await client.createExerciseTemplate({
            title: et.title,
            exercise_type: enums.exerciseType,
            equipment_category: enums.equipmentCategory,
            muscle_group: enums.primaryMuscleGroup,
            other_muscles: enums.secondaryMuscleGroups,
          });
          matched.set(et.id, created.id);
          customCreated.add(et.id);
        }
      }

      // e. Save all exercise template mappings (batched), scoped to new programId
      if (matched.size > 0) {
        const upsertTemplateStmt = db.prepare(
          `INSERT INTO exercise_template_mappings (user_id, program_template_id, hevy_template_id, is_custom, program_id)
           VALUES (?, ?, ?, ?, ?)
           ON CONFLICT(user_id, program_template_id) DO UPDATE SET
             hevy_template_id = excluded.hevy_template_id,
             is_custom = excluded.is_custom,
             program_id = excluded.program_id`
        );
        await db.batch(
          [...matched.entries()].map(([programTemplateId, hevyTemplateId]) =>
            upsertTemplateStmt.bind(
              userId,
              programTemplateId,
              hevyTemplateId,
              customCreated.has(programTemplateId) ? 1 : 0,
              programId
            )
          )
        );
      }

      // f. Create or update Hevy routines with folder grouping + dedup
      const allMappings = await getExerciseTemplateMappings(db, userId, programId);
      const existingRoutineMappings = await getRoutineMappings(db, userId, programId);
      const existingMappingsMap = new Map(
        existingRoutineMappings.map((m) => [m.program_routine_id, m.hevy_routine_id])
      );

      // Compute folder assignments and create/find folders
      const folderAssignments = computeFolderAssignments(program.routines, program.meta.title);
      const uniqueFolderNames = [...new Set(folderAssignments.map((a) => a.folderName))];
      const folderNameToId = new Map<string, number>();
      // Create folders in parallel, limited to 3 concurrent to avoid Hevy rate limits
      for (let i = 0; i < uniqueFolderNames.length; i += 3) {
        const batch = uniqueFolderNames.slice(i, i + 3);
        const results = await Promise.all(
          batch.map((name) => client.getOrCreateRoutineFolder(name))
        );
        for (let j = 0; j < batch.length; j++) {
          folderNameToId.set(batch[j], results[j].id);
        }
      }

      // Fetch existing Hevy routines for dedup by title+folder
      const existingHevyRoutines = await client.getAllRoutines();

      // Reconcile: decide create vs update for each routine
      const reconciliations = reconcileRoutines(
        folderAssignments, existingHevyRoutines, folderNameToId, existingMappingsMap
      );

      for (const recon of reconciliations) {
        const routine = program.routines.find((r) => r.id === recon.programRoutineId);
        if (!routine) continue;
        const payload = buildRoutinePayload(routine, allMappings);
        const folderId = folderNameToId.get(recon.folderName)!;

        if (recon.action === "update" && recon.existingHevyRoutineId) {
          await client.updateRoutine(recon.existingHevyRoutineId, {
            title: payload.title,
            exercises: payload.exercises,
          });
          routineIdMap.set(routine.id, recon.existingHevyRoutineId);
        } else {
          const created = await client.createRoutine({
            title: payload.title,
            folder_id: folderId,
            exercises: payload.exercises,
          });
          routineIdMap.set(routine.id, created.id);
        }
      }

      // g. Save all routine mappings (batched), scoped to new programId
      if (routineIdMap.size > 0) {
        const upsertRoutineStmt = db.prepare(
          `INSERT INTO routine_mappings (user_id, program_routine_id, hevy_routine_id, program_id)
           VALUES (?, ?, ?, ?)
           ON CONFLICT(user_id, program_routine_id) DO UPDATE SET
             hevy_routine_id = excluded.hevy_routine_id,
             program_id = excluded.program_id`
        );
        await db.batch(
          [...routineIdMap.entries()].map(([programRoutineId, hevyRoutineId]) =>
            upsertRoutineStmt.bind(userId, programRoutineId, hevyRoutineId, programId)
          )
        );
      }
    } catch (err) {
      console.error("Hevy sync failed during program activation (queue already saved):", err instanceof Error ? err.message : err);
    }
  }

  // 5. Bulk-set hevy_routine_id on queue items via routine_mappings
  if (routineIdMap.size > 0) {
    await bulkSetQueueItemRoutineIds(db, userId, routineIdMap);
  }
}

import type { UserRow, QueueItemRow, ExerciseTemplateMappingRow, RoutineMappingRow, ProgramRow, Program, BenchmarkResultRow } from "../types";
import { sha256Hex, encryptAesGcm } from "../utils/crypto";

export async function getUser(db: D1Database, userId: string): Promise<UserRow | null> {
  return db.prepare("SELECT * FROM users WHERE id = ?").bind(userId).first<UserRow>();
}

export async function upsertUser(
  db: D1Database,
  user: { id: string; active_program: string; template_id: string; start_date: string; hevy_api_key?: string; timezone?: string }
): Promise<void> {
  await db
    .prepare(
      `INSERT INTO users (id, active_program, template_id, start_date, hevy_api_key, timezone)
       VALUES (?, ?, ?, ?, ?, ?)
       ON CONFLICT(id) DO UPDATE SET
         active_program = excluded.active_program,
         template_id = excluded.template_id,
         start_date = excluded.start_date,
         hevy_api_key = COALESCE(excluded.hevy_api_key, users.hevy_api_key),
         timezone = COALESCE(excluded.timezone, users.timezone)`
    )
    .bind(user.id, user.active_program, user.template_id, user.start_date, user.hevy_api_key ?? null, user.timezone ?? null)
    .run();
}

/** Update program fields and return the existing API key in one roundtrip */
export async function updateUserProgram(
  db: D1Database,
  userId: string,
  activeProgram: string,
  templateId: string,
  startDate: string
): Promise<string | null> {
  await db
    .prepare("UPDATE users SET active_program = ?, template_id = ?, start_date = ? WHERE id = ?")
    .bind(activeProgram, templateId, startDate, userId)
    .run();
  const row = await db.prepare("SELECT hevy_api_key FROM users WHERE id = ?").bind(userId).first<{ hevy_api_key: string | null }>();
  return row?.hevy_api_key ?? null;
}

export async function getQueueItems(db: D1Database, userId: string, programId?: number): Promise<QueueItemRow[]> {
  const result = programId != null
    ? await db
        .prepare("SELECT * FROM queue_items WHERE user_id = ? AND program_id = ? ORDER BY position")
        .bind(userId, programId)
        .all<QueueItemRow>()
    : await db
        .prepare("SELECT * FROM queue_items WHERE user_id = ? ORDER BY position")
        .bind(userId)
        .all<QueueItemRow>();
  return result.results;
}

export async function insertQueueItems(
  db: D1Database,
  userId: string,
  items: Array<{ routine_id: string; position: number }>,
  programId?: number
): Promise<void> {
  const stmt = db.prepare(
    "INSERT INTO queue_items (user_id, routine_id, position, program_id) VALUES (?, ?, ?, ?)"
  );
  const batch = items.map((item) => stmt.bind(userId, item.routine_id, item.position, programId ?? null));
  await db.batch(batch);
}

export async function markQueueItemCompleted(
  db: D1Database,
  itemId: number,
  completedDate: string,
  hevyWorkoutId?: string,
  workoutData?: string
): Promise<void> {
  await db
    .prepare(
      "UPDATE queue_items SET status = 'completed', completed_date = ?, hevy_workout_id = ?, hevy_workout_data = ? WHERE id = ?"
    )
    .bind(completedDate, hevyWorkoutId ?? null, workoutData ?? null, itemId)
    .run();
}

/** Batch-mark multiple queue items as completed in a single D1 roundtrip */
export async function batchMarkQueueItemsCompleted(
  db: D1Database,
  items: Array<{ itemId: number; completedDate: string; workoutId: string; workoutData?: string }>
): Promise<void> {
  if (items.length === 0) return;
  await db.batch(
    items.map((item) =>
      db
        .prepare(
          "UPDATE queue_items SET status = 'completed', completed_date = ?, hevy_workout_id = ?, hevy_workout_data = ? WHERE id = ?"
        )
        .bind(item.completedDate, item.workoutId, item.workoutData ?? null, item.itemId)
    )
  );
}

/** Batch-mark multiple queue items as skipped (out of order — user moved past them) */
export async function batchMarkQueueItemsSkipped(db: D1Database, itemIds: number[]): Promise<void> {
  if (itemIds.length === 0) return;
  await db.batch(
    itemIds.map((itemId) =>
      db.prepare("UPDATE queue_items SET status = 'skipped' WHERE id = ?").bind(itemId)
    )
  );
}

export async function markQueueItemCompletedForUser(
  db: D1Database,
  itemId: number,
  userId: string,
  completedDate: string,
  hevyWorkoutId?: string
): Promise<void> {
  await db
    .prepare(
      "UPDATE queue_items SET status = 'completed', completed_date = ?, hevy_workout_id = ? WHERE id = ? AND user_id = ?"
    )
    .bind(completedDate, hevyWorkoutId ?? null, itemId, userId)
    .run();
}

export async function updateQueueItemHevyRoutineId(
  db: D1Database,
  itemId: number,
  routineId: string
): Promise<void> {
  await db
    .prepare("UPDATE queue_items SET hevy_routine_id = ? WHERE id = ?")
    .bind(routineId, itemId)
    .run();
}

export async function getExerciseTemplateMappings(
  db: D1Database,
  userId: string,
  programId?: number
): Promise<ExerciseTemplateMappingRow[]> {
  const result = programId != null
    ? await db
        .prepare("SELECT * FROM exercise_template_mappings WHERE user_id = ? AND program_id = ?")
        .bind(userId, programId)
        .all<ExerciseTemplateMappingRow>()
    : await db
        .prepare("SELECT * FROM exercise_template_mappings WHERE user_id = ?")
        .bind(userId)
        .all<ExerciseTemplateMappingRow>();
  return result.results;
}

export async function upsertExerciseTemplateMapping(
  db: D1Database,
  mapping: ExerciseTemplateMappingRow
): Promise<void> {
  await db
    .prepare(
      `INSERT INTO exercise_template_mappings (user_id, program_template_id, hevy_template_id, is_custom, program_id)
       VALUES (?, ?, ?, ?, ?)
       ON CONFLICT(user_id, program_template_id) DO UPDATE SET
         hevy_template_id = excluded.hevy_template_id,
         is_custom = excluded.is_custom,
         program_id = excluded.program_id`
    )
    .bind(mapping.user_id, mapping.program_template_id, mapping.hevy_template_id, mapping.is_custom, mapping.program_id ?? null)
    .run();
}

export async function getRoutineMappings(
  db: D1Database,
  userId: string,
  programId?: number
): Promise<RoutineMappingRow[]> {
  const result = programId != null
    ? await db
        .prepare("SELECT * FROM routine_mappings WHERE user_id = ? AND program_id = ?")
        .bind(userId, programId)
        .all<RoutineMappingRow>()
    : await db
        .prepare("SELECT * FROM routine_mappings WHERE user_id = ?")
        .bind(userId)
        .all<RoutineMappingRow>();
  return result.results;
}

export async function upsertRoutineMapping(
  db: D1Database,
  mapping: RoutineMappingRow
): Promise<void> {
  await db
    .prepare(
      `INSERT INTO routine_mappings (user_id, program_routine_id, hevy_routine_id, program_id)
       VALUES (?, ?, ?, ?)
       ON CONFLICT(user_id, program_routine_id) DO UPDATE SET
         hevy_routine_id = excluded.hevy_routine_id,
         program_id = excluded.program_id`
    )
    .bind(mapping.user_id, mapping.program_routine_id, mapping.hevy_routine_id, mapping.program_id ?? null)
    .run();
}

export async function bulkSetQueueItemRoutineIds(
  db: D1Database,
  userId: string,
  routineIdMap: Map<string, string>
): Promise<void> {
  if (routineIdMap.size === 0) return;
  const stmt = db.prepare(
    "UPDATE queue_items SET hevy_routine_id = ? WHERE user_id = ? AND routine_id = ?"
  );
  const batch = [...routineIdMap.entries()].map(([programRoutineId, hevyRoutineId]) =>
    stmt.bind(hevyRoutineId, userId, programRoutineId)
  );
  await db.batch(batch);
}

export async function insertProgram(
  db: D1Database,
  userId: string,
  jsonData: string
): Promise<number> {
  const deactivate = db
    .prepare("UPDATE programs SET is_active = 0 WHERE user_id = ? AND is_active = 1")
    .bind(userId);
  const insert = db
    .prepare("INSERT INTO programs (user_id, json_data) VALUES (?, ?)")
    .bind(userId, jsonData);
  const [, insertResult] = await db.batch([deactivate, insert]);

